// Find leads with no contact in 7+ days
const leads = $input.all();
const now = new Date();
const sevenDaysAgo = new Date(now - 7 * 24 * 60 * 60 * 1000);

const staleLeads = leads.filter(item => {
  const lead = item.json;
  if (lead.status === 'won' || lead.status === 'lost' || lead.status === 'cancelled') return false;
  if (!lead.last_updated && !lead.date) return true;
  const lastContact = new Date(lead.last_updated || lead.date);
  return lastContact < sevenDaysAgo;
});

const activeLeads = leads.filter(item => {
  const lead = item.json;
  return lead.status !== 'won' && lead.status !== 'lost' && lead.status !== 'cancelled';
});

return [{
  json: {
    stale_leads: staleLeads.map(i => i.json),
    active_leads: activeLeads.map(i => i.json),
    total_active: activeLeads.length,
    total_stale: staleLeads.length,
    review_date: now.toISOString().split('T')[0]
  }
}];
